import json,html
from pathlib import Path
out=Path('icon_set/work/sub-text-audit');rows=json.loads((out/'audit.json').read_text())
# Visual observations from all nine before/after sheets; numbers follow sheet order.
crowded={2,16,28,69,74,86,88,89,90,141,168,178,195,200,220,226,231,331}
for i,r in enumerate(rows,1):
 notes=[];confirmed=[]
 if 'fractional arc radii' in r['flags']:
  notes.append('Arc radii remain fractional. SVG radius correction can reintroduce fractions after endpoints are rounded. Reconstruct these arcs from shared grid geometry; check their silhouettes afterward.');confirmed.append('Arc grid exception')
 if 'stroke not 4' in r['flags']:
  notes.append('Dots were enlarged to a 32-unit stroke and 352-unit width. This is an incorrect text-height special case. Treat the three-dot menu mark as a symbol under icon sizing rules.');confirmed.append('Incorrect dot sizing')
 ht=r.get('high_resolution_topology')
 if ht:
  if ht[0]!=ht[1]:
   notes.append(f'Snapping changes connected parts / enclosed openings, confirmed at 16×: {ht[0]} → {ht[1]}. Restore openings and separation with glyph-aware grid fitting.');confirmed.append('Shape or separation changed')
  else:notes.append('Small openings change in the 4× raster but not at 16×. This is a fragile small-size detail; inspect at actual size before approving.')
 if i in crowded:notes.append('Visual concern: stacked text or symbols are too dense at a 32-unit total height with a 4-unit stroke. Reflow into a single line where meaning permits, using the available free width; otherwise revise the layout individually.')
 r.update(number=i,notes=notes,confirmed=confirmed,attention=bool(notes))
(out/'audit.json').write_text(json.dumps(rows,indent=2))
counts=dict(total=len(rows),confirmed=sum(bool(r['confirmed']) for r in rows),attention=sum(r['attention'] for r in rows))
summary=f"Reviewed all {len(rows)} text artworks. {counts['confirmed']} have confirmed geometry or sizing issues; {counts['attention']} need attention including small-size visual concerns. All 339 pass 32-unit ink height, integer path-point coordinates and unclipped bounds. This is an audit, not approval."
page='''<!doctype html><html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Full text sub-icon audit</title><style>body{font:15px system-ui;background:#f4f6f8;color:#20313d;margin:0;padding:24px}h1{font-size:26px}p{line-height:1.6}button,select,input{font:inherit;padding:9px;margin:5px;border:1px solid #b9c5ce;border-radius:5px}article{background:white;border:1px solid #d1d9df;border-radius:9px;padding:18px;margin:18px 0}.compare{display:grid;grid-template-columns:1fr 1fr;gap:16px}.art{overflow:auto;padding:14px 0;min-height:110px}.art img{display:block;max-width:none;height:96px}.native img{height:32px;max-width:none}small{color:#60717e}.issue{border-left:5px solid #c77934}.ok{border-left:5px solid #789b85}li{margin:10px 0;line-height:1.5}@media(max-width:650px){.compare{grid-template-columns:1fr}}a{color:#236d9c}</style><h1>Full text sub-icon audit</h1><p>SUMMARY</p><p>Compared height-fitted geometry before snapping with the current grid export. Inspected all nine comparison sheets; checked all path anchors/control points, ink bounds, stroke and arc radii. Raster opening/contact differences were rechecked at 16×. Original-reference wording and typeface provenance are not certified by this export audit.</p><p>No artwork or approval decisions changed in this audit.</p><input id="search" placeholder="Search name"><select id="filter"><option value="attention">Needs attention</option><option value="confirmed">Confirmed geometry / sizing issues</option><option value="all">All 339</option></select><p id="count"></p><div id="list"></div><script>const rows=DATA;const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function render(){const term=document.querySelector('#search').value.toLowerCase(),f=document.querySelector('#filter').value;const selected=rows.filter(r=>r.name.toLowerCase().includes(term)&&(f==='all'||(f==='confirmed'?r.confirmed.length:r.attention)));document.querySelector('#count').textContent=selected.length+' artworks shown';document.querySelector('#list').innerHTML=selected.map(r=>`<article class="${r.attention?'issue':'ok'}"><h2>${r.number}. ${esc(r.name)}</h2><small>${esc(r.key)}</small><p>${r.width} × 32 ink · stroke ${r.stroke} · ${r.confirmed.map(esc).join(', ')|| (r.attention?'Visual review needed':'No issue detected by this pass')}</p><div class="compare"><div><b>Height fit before snapping</b><div class="art"><img src="${r.before_uri}"></div><div class="native"><img src="${r.before_uri}"></div></div><div><b>Current grid export</b><div class="art"><img src="${r.after_uri}"></div><div class="native"><img src="${r.after_uri}"></div></div></div><ul>${r.notes.map(n=>'<li>'+esc(n)+'</li>').join('')}</ul></article>`).join('')}document.querySelector('#search').oninput=render;document.querySelector('#filter').onchange=render;render()</script></html>'''.replace('SUMMARY',html.escape(summary)).replace('DATA',json.dumps(rows).replace('</','<\\/'))
(out/'index.html').write_text(page);Path('icon_set/dist/gallery/sub-text-audit.html').write_text(page)
(out/'summary.md').write_text('# Text sub-icon audit\n\n'+summary+'\n\n'+ '\n'.join('- **'+r['name']+'**: '+' '.join(r['notes']) for r in rows if r['attention']))
print(counts)
